-- Curva base (sin incrementales) de El Tordillo y LT_PQO, del archivo
-- Produccion_ETLTPQ_Proyectada_06.2026 (hoja "Prod real Beto ET (2)",
-- columnas "Curva Base por Concesion"). bbl_petroleo/mcf_gas ya vienen
-- convertidos de m3/d y Mm3/d a volumen mensual (factor 6.2898 bbl/m3 y
-- 35.3147 ft3/m3, multiplicado por dias del mes), igual que el importador
-- de Excel de la app. mes_offset 0 = enero 2026.
--
-- Requiere que ya exista un pozo_tipo categoria='basico' para cada
-- yacimiento (sección "6. Pozo tipo") -- si no, creálo antes de correr esto.

with dest as (
  select
    (select pt.id from pozos_tipo pt join yacimientos y on y.id = pt.yacimiento_id
       where y.nombre = 'El Tordillo' and pt.categoria = 'basico' limit 1) as et_id,
    (select pt.id from pozos_tipo pt join yacimientos y on y.id = pt.yacimiento_id
       where y.nombre = 'LT_PQO' and pt.categoria = 'basico' limit 1) as lt_id
)
insert into curvas_produccion (pozo_tipo_id, mes_offset, bbl_petroleo, mcf_gas)
